import React, { useState, useEffect } from "react";
import NavigationLinks from "./NavigationLinks";

function LCKSchedule() {
  const [htmlContent, setHtmlContent] = useState("");
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchData() {
      try {
        const url = "https://lckschedule.hung1504.workers.dev/";
        const response = await fetch(url);
        if (!response.ok)
          throw new Error(`HTTP Error! Status: ${response.status}`);

        const html = await response.text();

        // Lấy phần body bên trong
        setHtmlContent(html);
        // const bodyMatch = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
        // if (bodyMatch && bodyMatch[1]) {
        //   setHtmlContent(bodyMatch[1]);
        // } else {
        //   setHtmlContent("Không tìm thấy nội dung để hiển thị.");
        // }
      } catch (err) {
        setError(err.message);
      }
    }
    fetchData();
  }, []);

  return (
    <div>
      <NavigationLinks />
      <div style={{ marginLeft: 10 }}>
        {error && <p style={{ color: "red" }}>Lỗi: {error}</p>}
        {!error && htmlContent && (
          <div dangerouslySetInnerHTML={{ __html: htmlContent }} />
        )}
        {!error && !htmlContent && <p>Đang tải dữ liệu...</p>}
      </div>
    </div>
  );
}

export default LCKSchedule;
