import React, { useEffect, useState, useCallback } from "react";
import Highcharts from "highcharts";
import HighchartsReact from "highcharts-react-official";

// GMT+7
Highcharts.setOptions({
  time: { timezoneOffset: -7 * 60 },
});

const API_ENDPOINTS = {
  PLOT_LINE: "https://bgapidatafeed.vps.com.vn/getlistindexdetail/10,02,11,03",
  CHART_DATA:
    "https://histdatafeed.vps.com.vn/tradingview/historiesnearest?symbols=VNINDEX&props=o,v,t&resolution=1",
};

const VNINDEX_MC_CODE = "10";
const Y_AXIS_PADDING_FACTOR = 0.05;
const UPDATE_INTERVAL_MS = 60000; // 1 minute

const StockChart = () => {
  const [plotLineValue, setPlotLineValue] = useState(null);
  const [chartOptions, setChartOptions] = useState(null);
  const [noData, setNoData] = useState(false);

  // Hàm fetch dữ liệu chart
  const fetchChartData = useCallback(async (currentPlotLine) => {
    try {
      const response = await fetch(API_ENDPOINTS.CHART_DATA);
      const data = await response.json();

      if (data?.VNINDEX?.s === "no_data") {
        setNoData(true);
        setChartOptions(null);
        return;
      } else {
        setNoData(false);
      }

      const today = new Date();
      const yyyy = today.getFullYear();
      const mm = today.getMonth();
      const dd = today.getDate();
      const createDate = (hour, minute) =>
        new Date(yyyy, mm, dd, hour, minute).getTime();

      const start9h = createDate(9, 0);
      const start915 = createDate(9, 15);
      const end1445 = createDate(14, 45);

      const ticks = [
        createDate(9, 0),
        createDate(10, 0),
        createDate(11, 0),
        createDate(12, 0),
        createDate(14, 0),
      ];

      let indexData = [];
      if (Array.isArray(data?.VNINDEX?.t) && Array.isArray(data?.VNINDEX?.o)) {
        // Flat dữ liệu từ 9h đến 9h15 bằng plotLineValue
        if (typeof currentPlotLine === "number" && !isNaN(currentPlotLine)) {
          for (let ts = start9h; ts <= start915; ts += 60000) {
            indexData.push([ts, currentPlotLine]);
          }
        }
        // Actual data
        for (let i = 0; i < data.VNINDEX.t.length; i++) {
          const time = Number(data.VNINDEX.t[i]) * 1000;
          const value = Number(data.VNINDEX.o[i]);
          if (!isNaN(time) && !isNaN(value)) {
            indexData.push([time, value]);
          }
        }
      }

      const zones =
        typeof currentPlotLine === "number" && !isNaN(currentPlotLine)
          ? [{ value: currentPlotLine, color: "#FF0000" }, { color: "#00FF00" }]
          : [{ color: "#00FF00" }];

      const minX = indexData.length
        ? Math.min(...indexData.map((d) => d[0]))
        : start9h;
      const yValues = indexData.map((d) => d[1]);
      const minY = yValues.length ? Math.min(...yValues) : 0;
      const maxY = yValues.length ? Math.max(...yValues) : 0;
      const padding = (maxY - minY) * Y_AXIS_PADDING_FACTOR;

      const validTicks = ticks.filter((tick) => !isNaN(tick));
      const validIndexData = indexData.filter(
        (d) => Array.isArray(d) && !isNaN(d[0]) && !isNaN(d[1])
      );

      // Giữ nguyên toàn bộ code vẽ chart
      setChartOptions({
        chart: {
          width: 250,
          height: 90,
          backgroundColor: "#1E1E1E",
          plotBackgroundColor: "#1E1E1E",
          spacing: [0, 0, 0, 0],
          margin: [0, 0, 0, 0],
        },
        title: { text: null },
        credits: { enabled: false },
        legend: { enabled: false },
        xAxis: {
          type: "datetime",
          labels: { style: { color: "#B0B0B0", fontSize: "9px" } },
          lineColor: "#888",
          tickColor: "#888",
          tickPositions: validTicks,
          breaks: [],
          min: minX,
          max: end1445,
        },
        yAxis: [
          {
            title: { text: null },
            labels: { enabled: false },
            gridLineWidth: 0,
            plotLines:
              typeof currentPlotLine === "number" && !isNaN(currentPlotLine)
                ? [
                    {
                      value: currentPlotLine,
                      color: "yellow",
                      dashStyle: "Dash",
                      width: 2,
                      zIndex: 5,
                      label: {
                        text: currentPlotLine.toLocaleString("en-US", {
                          minimumFractionDigits: 2,
                          maximumFractionDigits: 2,
                        }),
                        align: "center",
                        style: {
                          color: "#FFFFFF",
                          fontWeight: "bold",
                          fontSize: "14px",
                          textOutline: "2px contrast",
                        },
                        y: -5,
                      },
                    },
                  ]
                : [],
            startOnTick: false,
            endOnTick: false,
            min: minY - padding,
            max: maxY + padding,
          },
        ],
        series: [
          {
            name: "VNINDEX",
            type: "line",
            data: validIndexData,
            yAxis: 0,
            color: "#00FF00",
            zones: zones,
            lineWidth: 1.5,
            marker: { enabled: false },
          },
        ],
        tooltip: { enabled: false },
      });
    } catch (error) {
      console.error("Lỗi tải dữ liệu biểu đồ:", error);
    }
  }, []);

  // Fetch lần đầu song song
  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        const [plotLineRes, chartRes] = await Promise.all([
          fetch(API_ENDPOINTS.PLOT_LINE).then((r) => r.json()),
          fetch(API_ENDPOINTS.CHART_DATA).then((r) => r.json()),
        ]);

        let initialPlotLine = null;
        if (Array.isArray(plotLineRes)) {
          const vnindexData = plotLineRes.find(
            (item) => item.mc === VNINDEX_MC_CODE
          );
          if (
            vnindexData &&
            vnindexData.oIndex &&
            !isNaN(Number(vnindexData.oIndex))
          ) {
            initialPlotLine = Number(vnindexData.oIndex);
            setPlotLineValue(initialPlotLine);
          }
        }

        // render chart ngay lập tức
        if (chartRes) {
          await fetchChartData(initialPlotLine);
        }

        // Cập nhật định kỳ chỉ cho chartData
        const interval = setInterval(
          () => fetchChartData(initialPlotLine),
          UPDATE_INTERVAL_MS
        );
        return () => clearInterval(interval);
      } catch (error) {
        console.error("Lỗi fetch dữ liệu ban đầu:", error);
      }
    };

    fetchInitialData();
  }, [fetchChartData]);

  if (noData) {
    return (
      <div
        style={{
          width: "250px",
          height: "90px",
          background: "#1E1E1E",
          color: "#fff",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div>Index</div>
        <div style={{ fontWeight: "bold", fontSize: "16px", marginTop: 4 }}>
          {typeof plotLineValue === "number" && !isNaN(plotLineValue)
            ? plotLineValue.toLocaleString("en-US", {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
              })
            : "--"}
        </div>
      </div>
    );
  }

  if (!chartOptions) {
    return (
      <div style={{ width: "250px", height: "90px", background: "#1E1E1E" }} />
    );
  }

  return (
    <div style={{ width: "250px", height: "90px", overflow: "hidden" }}>
      <HighchartsReact highcharts={Highcharts} options={chartOptions} />
    </div>
  );
};

export default StockChart;
